  1	package com.pousada;
  2	
  3	import com.pousada.api.ApiHandlers;
  4	import com.pousada.business.ReservationService;
  5	import com.pousada.db.*;
  6	import io.javalin.Javalin;
  7	
  8	import java.math.BigDecimal;
  9	import java.util.ArrayList;
 10	import java.util.List;
 11	
 12	public class Application {
 13	    public static void main(String[] args) throws Exception {
 14	        String dbUrl = System.getenv("DB_URL");
 15	        String dbUser = System.getenv("DB_USER");
 16	        String dbPassword = System.getenv("DB_PASSWORD");
 17	        String portStr = System.getenv("PORT");
 18	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 19	
 20	        Database database = new Database(dbUrl, dbUser, dbPassword);
 21	        database.initialize();
 22	
 23	        initializeRooms(database);
 24	
 25	        RoomRepository roomRepo = new RoomRepository(database);
 26	        ReservationRepository reservationRepo = new ReservationRepository(database);
 27	        MessageRepository messageRepo = new MessageRepository(database);
 28	        ReservationService reservationService = new ReservationService(reservationRepo, roomRepo, messageRepo);
 29	
 30	        ApiHandlers handlers = new ApiHandlers(roomRepo, reservationService, reservationRepo, messageRepo);
 31	
 32	        Javalin app = Javalin.create()
 33	                .start(port);
 34	
 35	        app.get("/rooms", handlers::getRooms);
 36	        app.post("/reservations", handlers::createReservation);
 37	        app.get("/reservations/{id}", handlers::getReservation);
 38	        app.post("/reservations/{id}/confirmation", handlers::confirmReservation);
 39	        app.post("/reservations/{id}/cancellation", handlers::cancelReservation);
 40	        app.post("/reservations/{id}/check-in", handlers::checkIn);
 41	        app.post("/reservations/{id}/check-out", handlers::checkOut);
 42	        app.get("/reservations/{id}/document", handlers::getDocument);
 43	        app.get("/messages", handlers::getMessages);
 44	        app.get("/reports/occupancy", handlers::getOccupancyReport);
 45	        app.get("/reports/revenue", handlers::getRevenueReport);
 46	        app.get("/reports/tourism-tax", handlers::getTourismTaxReport);
 47	        app.get("/reports/rate-plans", handlers::getRatePlanReport);
 48	
 49	        System.out.println("Pousada Maré Alta started on port " + port);
 50	    }
 51	
 52	    private static void initializeRooms(Database database) throws Exception {
 53	        try (java.sql.Connection conn = database.getConnection()) {
 54	            java.sql.Statement stmt = conn.createStatement();
 55	            java.sql.ResultSet rs = stmt.executeQuery("SELECT COUNT(*) as count FROM rooms");
 56	            rs.next();
 57	            if (rs.getInt("count") == 0) {
 58	                List<Database.RoomData> rooms = new ArrayList<>();
 59	                rooms.add(new Database.RoomData(101, "STANDARD", 2, new BigDecimal("249.90")));
 60	                rooms.add(new Database.RoomData(102, "STANDARD", 2, new BigDecimal("249.90")));
 61	                rooms.add(new Database.RoomData(201, "DELUXE", 3, new BigDecimal("389.90")));
 62	                rooms.add(new Database.RoomData(202, "DELUXE", 3, new BigDecimal("389.90")));
 63	                rooms.add(new Database.RoomData(301, "SUITE", 4, new BigDecimal("579.90")));
 64	                database.insertRooms(rooms);
 65	            }
 66	            stmt.close();
 67	        }
 68	    }
 69	}
 70	package com.pousada.api;
 71	
 72	import com.google.gson.Gson;
 73	import com.google.gson.GsonBuilder;
 74	import com.google.gson.JsonElement;
 75	import com.google.gson.JsonObject;
