 21	package com.pousada.business;
 22	
 23	import com.pousada.db.*;
 24	import com.pousada.models.*;
 25	import com.pousada.utils.PricingUtils;
 26	
 27	import java.math.BigDecimal;
 28	import java.time.LocalDate;
 29	import java.util.List;
 30	import java.util.Optional;
 31	
 32	public class ReservationService {
 33	    private final ReservationRepository reservationRepo;
 34	    private final RoomRepository roomRepo;
 35	    private final MessageRepository messageRepo;
 36	
 37	    public ReservationService(ReservationRepository reservationRepo, RoomRepository roomRepo, MessageRepository messageRepo) {
 38	        this.reservationRepo = reservationRepo;
 39	        this.roomRepo = roomRepo;
 40	        this.messageRepo = messageRepo;
 41	    }
 42	
 43	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 44	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) throws Exception {
 45	        Optional<Room> room = roomRepo.findByNumber(roomNumber);
 46	        if (room.isEmpty()) {
 47	            throw new ApiException(404, "ROOM_NOT_FOUND", "Room not found");
 48	        }
 49	
 50	        if (guests < 1) {
 51	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
 52	        }
 53	
 54	        if (guests > room.get().getCapacity()) {
 55	            throw new ApiException(422, "CAPACITY_EXCEEDED", "Too many guests for this room");
 56	        }
 57	
 58	        if (!checkOut.isAfter(checkIn)) {
 59	            throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
 60	        }
 61	
 62	        List<Reservation> conflicts = reservationRepo.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
 63	        if (!conflicts.isEmpty()) {
 64	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for these dates");
 65	        }
 66	
 67	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 68	        BigDecimal[] nightlyPrices = new BigDecimal[nights];
 69	        for (int i = 0; i < nights; i++) {
 70	            LocalDate night = checkIn.plusDays(i);
 71	            nightlyPrices[i] = PricingUtils.calculateNightlyPrice(room.get().getNightlyRate(), night);
 72	        }
 73	
 74	        BigDecimal subtotal = PricingUtils.calculateSubtotal(nightlyPrices);
 75	        BigDecimal discount = PricingUtils.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
 76	        BigDecimal total = PricingUtils.calculateTotal(subtotal, discount);
 77	
 78	        return reservationRepo.create(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
 79	                guests, ratePlan, nights, subtotal, discount, total);
 80	    }
 81	
 82	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws Exception {
 83	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
 84	        if (reservation.isEmpty()) {
 85	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
 86	        }
 87	
 88	        Reservation res = reservation.get();
 89	        if (res.getStatus() != ReservationStatus.PENDING) {
 90	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot confirm a reservation that is not pending");
 91	        }
 92	
 93	        Reservation confirmed = res.withStatus(ReservationStatus.CONFIRMED)
 94	                .withAmountPaid(amountPaid);
 95	        reservationRepo.update(confirmed);
 96	
 97	        sendConfirmationEmail(confirmed);
 98	
 99	        return confirmed;
100	    }
101	
102	    public Reservation cancelReservation(long reservationId) throws Exception {
103	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
104	        if (reservation.isEmpty()) {
105	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
106	        }
107	
108	        Reservation res = reservation.get();
109	        if (res.getStatus() == ReservationStatus.CHECKED_OUT || res.getStatus() == ReservationStatus.CANCELLED) {
110	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot cancel a reservation in this state");
111	        }
112	
113	        if (res.getStatus() == ReservationStatus.CHECKED_IN) {
114	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot cancel a checked-in reservation");
115	        }
116	
117	        BigDecimal refund = BigDecimal.ZERO;
118	        if (res.getStatus() == ReservationStatus.CONFIRMED && res.getRatePlan() == RatePlan.STANDARD) {
119	            refund = res.getAmountPaid();
120	        }
121	
122	        Reservation cancelled = res.withStatus(ReservationStatus.CANCELLED)
123	                .withRefund(refund);
124	        reservationRepo.update(cancelled);
125	
126	        return cancelled;
127	    }
128	
129	    public Reservation checkIn(long reservationId) throws Exception {
130	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
131	        if (reservation.isEmpty()) {
132	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
133	        }
134	
135	        Reservation res = reservation.get();
136	        if (res.getStatus() != ReservationStatus.CONFIRMED) {
137	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot check-in a reservation that is not confirmed");
138	        }
139	
140	        Reservation checkedIn = res.withStatus(ReservationStatus.CHECKED_IN);
141	        reservationRepo.update(checkedIn);
142	
143	        return checkedIn;
144	    }
145	
146	    public Reservation checkOut(long reservationId) throws Exception {
147	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
148	        if (reservation.isEmpty()) {
149	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
150	        }
151	
152	        Reservation res = reservation.get();
153	        if (res.getStatus() != ReservationStatus.CHECKED_IN) {
154	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot check-out a reservation that is not checked-in");
155	        }
156	
157	        Reservation checkedOut = res.withStatus(ReservationStatus.CHECKED_OUT);
158	        reservationRepo.update(checkedOut);
159	
160	        return checkedOut;
161	    }
162	
163	    private void sendConfirmationEmail(Reservation reservation) throws Exception {
164	        String subject = "Reserva confirmada - Pousada Maré Alta";
165	        String comprovante = generateComprovante(reservation);
166	        String body = """
167	            Olá, %s!
168	
169	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
170	
171	            %s
172	
173	            A entrada é a partir das 14h, e a saída, até as 12h.
174	            Até breve!
175	            """.formatted(reservation.getGuestName(), comprovante);
176	
177	        messageRepo.create("EMAIL", reservation.getGuestEmail(), subject, body);
178	    }
179	
180	    public String generateComprovante(Reservation reservation) throws Exception {
181	        Optional<Room> room = roomRepo.findByNumber(reservation.getRoomNumber());
182	        if (room.isEmpty()) {
183	            throw new Exception("Room not found");
184	        }
185	
186	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
187	        String discountLine = reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0
188	                ? "Desconto: " + PricingUtils.formatCurrency(reservation.getDiscount()) + "\n"
189	                : "";
190	
191	        return String.format("""
192	                Comprovante de reserva nº %d
193	                Hóspede: %s (CPF %s)
194	                Quarto: %d (%s)
195	                Entrada: %s | Saída: %s | %s
196	                Diárias: %s
197	                %sTotal: %s""",
198	                reservation.getId(),
199	                reservation.getGuestName(),
200	                reservation.getGuestCpf(),
201	                reservation.getRoomNumber(),
202	                room.get().getType().getLabel(),
203	                PricingUtils.formatDate(reservation.getCheckIn()),
204	                PricingUtils.formatDate(reservation.getCheckOut()),
205	                nightsText,
206	                PricingUtils.formatCurrency(reservation.getSubtotal()),
207	                discountLine,
208	                PricingUtils.formatCurrency(reservation.getTotal())
209	        );
210	    }
211	}
212	package com.pousada.utils;
213	
214	import java.math.BigDecimal;
215	import java.math.RoundingMode;
216	import java.time.LocalDate;
217	
218	public class PricingUtils {
219	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
220	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
221	
222	    public static boolean isHighSeason(LocalDate date) {
223	        int month = date.getMonthValue();
224	        int day = date.getDayOfMonth();
225	
226	        if (month == 7) {
227	            return true;
228	        }
229	
230	        if (month == 12 || month == 1 || month == 2) {
231	            if (month == 12) {
232	                return day >= 15;
233	            }
234	            if (month == 2) {
235	                return day <= 28;
236	            }
237	            return true;
238	        }
239	
240	        return false;
241	    }
242	
243	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate night) {
244	        BigDecimal price = baseRate;
245	        if (isHighSeason(night)) {
246	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
247	        }
248	        return roundToPair(price);
249	    }
250	
251	    public static BigDecimal calculateSubtotal(BigDecimal[] nightlyPrices) {
252	        BigDecimal sum = BigDecimal.ZERO;
253	        for (BigDecimal price : nightlyPrices) {
254	            sum = sum.add(price);
255	        }
256	        return roundToPair(sum);
257	    }
258	
259	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
260	        if (!isNonRefundable) {
261	            return BigDecimal.ZERO;
262	        }
263	        BigDecimal discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
264	        return roundToPair(discount);
265	    }
266	
267	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
268	        return roundToPair(subtotal.subtract(discount));
269	    }
270	
271	    public static BigDecimal roundToPair(BigDecimal value) {
272	        return value.setScale(2, RoundingMode.HALF_EVEN);
273	    }
274	
275	    public static String formatCurrency(BigDecimal value) {
276	        if (value == null) {
277	            return "";
278	        }
279	        return "R$ " + String.format("%.2f", value).replace(".", ",");
280	    }
281	
282	    public static String formatDate(LocalDate date) {
283	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
284	    }
285	
286	    public static String formatDateIso(LocalDate date) {
287	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
288	    }
289	}

