 64	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for these dates");
 65	        }
 66	
 67	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 68	        BigDecimal[] nightlyPrices = new BigDecimal[nights];
 69	        for (int i = 0; i < nights; i++) {
 70	            LocalDate night = checkIn.plusDays(i);
 71	            nightlyPrices[i] = PricingUtils.calculateNightlyPrice(room.get().getNightlyRate(), night);
 72	        }
 73	
 74	        BigDecimal subtotal = PricingUtils.calculateSubtotal(nightlyPrices);
 75	        BigDecimal discount = PricingUtils.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
 76	        BigDecimal total = PricingUtils.calculateTotal(subtotal, discount);
 77	
 78	        return reservationRepo.create(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
 79	                guests, ratePlan, nights, subtotal, discount, total);
 80	    }
