111	            reservationCounts.put(RatePlan.NON_REFUNDABLE, 0);
112	            amounts.put(RatePlan.STANDARD, BigDecimal.ZERO);
113	            amounts.put(RatePlan.NON_REFUNDABLE, BigDecimal.ZERO);
114	
115	            List<Reservation> reservations = reservationRepo.findByMonthStarting(month, year);
116	
117	            for (Reservation res : reservations) {
118	                RatePlan plan = res.getRatePlan();
119	                reservationCounts.put(plan, reservationCounts.get(plan) + 1);
120	
121	                BigDecimal netAmount = res.getAmountPaid();
122	                if (res.getRefund() != null) {
123	                    netAmount = netAmount.subtract(res.getRefund());
124	                }
125	                amounts.put(plan, amounts.get(plan).add(netAmount));
126	            }
127	
128	            BigDecimal totalAmount = BigDecimal.ZERO;
129	            int totalReservations = 0;
130	
131	            for (RatePlan plan : RatePlan.values()) {
132	                int count = reservationCounts.get(plan);
133	                BigDecimal amount = amounts.get(plan);
134	                totalReservations += count;
135	                totalAmount = totalAmount.add(amount);
136	
137	                sb.append(generateCsvRow(
138	                        plan.getLabel(),
139	                        String.valueOf(count),
140	                        String.format("%.2f", amount)
141	                )).append("\n");
142	            }
143	
144	            sb.append(generateCsvRow(
145	                    "total",
146	                    String.valueOf(totalReservations),
147	                    String.format("%.2f", totalAmount)
148	            )).append("\n");
149	
150	            return sb.toString();
151	        } catch (SQLException e) {
152	            throw new RuntimeException(e);
153	        }
154	    }
