186	    public Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
187	                             LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
188	                             int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) throws SQLException {
189	        String sql = """
190	            INSERT INTO reservations
191	            (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests,
192	             rate_plan, nights, subtotal, discount, total, status, amount_paid)
193	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
194	            RETURNING id
195	            """;
196	
197	        try (Connection conn = database.getConnection();
198	             PreparedStatement stmt = conn.prepareStatement(sql)) {
199	            stmt.setInt(1, roomNumber);
200	            stmt.setString(2, guestName);
201	            stmt.setString(3, guestEmail);
202	            stmt.setString(4, guestCpf);
203	            stmt.setDate(5, java.sql.Date.valueOf(checkIn));
204	            stmt.setDate(6, java.sql.Date.valueOf(checkOut));
205	            stmt.setInt(7, guests);
206	            stmt.setString(8, ratePlan.getLabel());
207	            stmt.setInt(9, nights);
208	            stmt.setBigDecimal(10, subtotal);
209	            stmt.setBigDecimal(11, discount);
210	            stmt.setBigDecimal(12, total);
211	            stmt.setString(13, ReservationStatus.PENDING.getLabel());
212	            stmt.setBigDecimal(14, BigDecimal.ZERO);
213	
214	            try (ResultSet rs = stmt.executeQuery()) {
215	                if (rs.next()) {
216	                    long id = rs.getLong("id");
217	                    return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
218	                            checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total,
219	                            ReservationStatus.PENDING, BigDecimal.ZERO, null);
220	                }
221	            }
222	        }
223	
224	        throw new SQLException("Failed to create reservation");
225	    }
226	
227	    public Optional<Reservation> findById(long id) throws SQLException {
228	        String sql = """
229	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
230	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
231	            FROM reservations WHERE id = ?
232	            """;
233	
234	        try (Connection conn = database.getConnection();
235	             PreparedStatement stmt = conn.prepareStatement(sql)) {
236	            stmt.setLong(1, id);
237	            try (ResultSet rs = stmt.executeQuery()) {
238	                if (rs.next()) {
239	                    return Optional.of(mapToReservation(rs));
240	                }
241	            }
242	        }
243	
244	        return Optional.empty();
245	    }
