247	    public void update(Reservation reservation) throws SQLException {
248	        String sql = """
249	            UPDATE reservations
250	            SET status = ?, amount_paid = ?, refund = ?
251	            WHERE id = ?
252	            """;
253	
254	        try (Connection conn = database.getConnection();
255	             PreparedStatement stmt = conn.prepareStatement(sql)) {
256	            stmt.setString(1, reservation.getStatus().getLabel());
257	            stmt.setBigDecimal(2, reservation.getAmountPaid());
258	            stmt.setBigDecimal(3, reservation.getRefund());
259	            stmt.setLong(4, reservation.getId());
260	            stmt.executeUpdate();
261	        }
262	    }
263	
264	    public List<Reservation> findByRoomAndDateRange(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
265	        String sql = """
266	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
267	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
268	            FROM reservations
269	            WHERE room_number = ?
270	            AND status != ?
271	            AND NOT (check_out <= ? OR check_in >= ?)
272	            """;
273	
274	        List<Reservation> reservations = new ArrayList<>();
275	        try (Connection conn = database.getConnection();
276	             PreparedStatement stmt = conn.prepareStatement(sql)) {
277	            stmt.setInt(1, roomNumber);
278	            stmt.setString(2, ReservationStatus.CANCELLED.getLabel());
279	            stmt.setDate(3, java.sql.Date.valueOf(checkIn));
280	            stmt.setDate(4, java.sql.Date.valueOf(checkOut));
281	
282	            try (ResultSet rs = stmt.executeQuery()) {
283	                while (rs.next()) {
284	                    reservations.add(mapToReservation(rs));
285	                }
286	            }
287	        }
288	
289	        return reservations;
290	    }
291	
292	    public List<Reservation> findByMonthStarting(int month, int year) throws SQLException {
293	        LocalDate monthStart = LocalDate.of(year, month, 1);
294	        LocalDate monthEnd = monthStart.withDayOfMonth(monthStart.lengthOfMonth());
295	
296	        String sql = """
297	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
298	                   guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
299	            FROM reservations
300	            WHERE check_in >= ? AND check_in <= ?
301	            AND status IN (?, ?, ?)
302	            ORDER BY check_in, id
303	            """;
304	
305	        List<Reservation> reservations = new ArrayList<>();
306	        try (Connection conn = database.getConnection();
307	             PreparedStatement stmt = conn.prepareStatement(sql)) {
308	            stmt.setDate(1, java.sql.Date.valueOf(monthStart));
309	            stmt.setDate(2, java.sql.Date.valueOf(monthEnd));
310	            stmt.setString(3, ReservationStatus.CONFIRMED.getLabel());
311	            stmt.setString(4, ReservationStatus.CHECKED_IN.getLabel());
312	            stmt.setString(5, ReservationStatus.CHECKED_OUT.getLabel());
313	
314	            try (ResultSet rs = stmt.executeQuery()) {
315	                while (rs.next()) {
316	                    reservations.add(mapToReservation(rs));
317	                }
318	            }
319	        }
320	
321	        return reservations;
322	    }
323	
324	    private Reservation mapToReservation(ResultSet rs) throws SQLException {
325	        long id = rs.getLong("id");
326	        int roomNumber = rs.getInt("room_number");
327	        String guestName = rs.getString("guest_name");
328	        String guestEmail = rs.getString("guest_email");
329	        String guestCpf = rs.getString("guest_cpf");
330	        LocalDate checkIn = rs.getDate("check_in").toLocalDate();
331	        LocalDate checkOut = rs.getDate("check_out").toLocalDate();
332	        int guests = rs.getInt("guests");
333	        RatePlan ratePlan = RatePlan.fromLabel(rs.getString("rate_plan"));
334	        int nights = rs.getInt("nights");
335	        BigDecimal subtotal = rs.getBigDecimal("subtotal");
336	        BigDecimal discount = rs.getBigDecimal("discount");
337	        BigDecimal total = rs.getBigDecimal("total");
338	        ReservationStatus status = ReservationStatus.fromLabel(rs.getString("status"));
339	        BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
340	        BigDecimal refund = rs.getBigDecimal("refund");
341	
342	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
343	                checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total,
344	                status, amountPaid, refund);
345	    }
346	}
